# shellcheck shell=sh
# Generated by matugen from the current wallpaper -- do not edit by hand.
# Edit templates/console_colors.sh in the dotfiles repo instead.
#
# NixOS's console.colors option is baked in at build time, so it cannot follow
# matugen, which regenerates the palette at runtime on every wallpaper change.
# Instead this sets the Linux virtual console palette at runtime using the
# ESC ] P <index> RRGGBB sequence that the kernel console driver understands.
#
# Sourced from the shell only when $TERM = linux; see modules/home-manager/shell.nix.
#
# The hues mirror templates/kitty_theme.conf: canonical ANSI colors harmonized
# toward the wallpaper's primary, rather than raw base16 values. Deriving the
# ANSI slots straight from base16 makes "red" come out grey on a desaturated
# wallpaper, which is useless in a TTY where color is the only signal you get.

# $1 = palette index (single hex digit), $2 = color, with or without a leading '#'
set_color() {
	printf '\033]P%s%s' "$1" "${2#\#}"
}

# black
set_color 0 '{{colors.surface_container.default.hex}}'
set_color 8 '{{colors.surface_container_highest.default.hex}}'

# red
set_color 1 '{{"#cc0403" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 55}}'
set_color 9 '{{"#ff5555" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 68}}'

# green
set_color 2 '{{"#19cb00" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 55}}'
set_color a '{{"#50fa7b" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 68}}'

# yellow
set_color 3 '{{"#cecb00" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 55}}'
set_color b '{{"#f1fa8c" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 72}}'

# blue
set_color 4 '{{"#0d73cc" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 55}}'
set_color c '{{"#6272a4" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 68}}'

# magenta
set_color 5 '{{"#cb1ed1" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 55}}'
set_color d '{{"#ff79c6" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 68}}'

# cyan
set_color 6 '{{"#0dcdcd" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 55}}'
set_color e '{{"#8be9fd" | to_color | harmonize: {{colors.primary.default.hex | to_color}} | set_lightness: 72}}'

# white
set_color 7 '{{colors.on_surface_variant.default.hex}}'
set_color f '{{colors.on_surface.default.hex}}'

unset -f set_color

# repaint the console with the new palette
printf '\033[2J\033[H'
